import { ReactNode, useEffect, useMemo, useState } from 'react'
import { Link, Route, Routes, useLocation, useNavigate } from 'react-router-dom'
import { api, ApiError, Department, Model, Profile, User } from './api/client'
import { useI18n } from './i18n'
import {
  App as AntApp, Alert, Avatar, Badge, Breadcrumb, Button, Card, Checkbox, Col, Descriptions, Divider, Drawer, Dropdown,
  Empty, Form, Input, InputNumber, Layout, Menu, Modal, Popconfirm, message, Row, Segmented, Select, Space, Spin, Statistic, Steps,
  Switch, Table, Tabs, Tag, Tree, Typography,
} from 'antd'
import type { MenuProps } from 'antd'
import {
  ApartmentOutlined, AppstoreOutlined, AuditOutlined, BarChartOutlined, BookOutlined, CheckCircleOutlined, CodeOutlined,
  DashboardOutlined, DownOutlined, FileSearchOutlined, KeyOutlined, LogoutOutlined, MenuFoldOutlined, MenuUnfoldOutlined,
  MonitorOutlined, SafetyCertificateOutlined, SettingOutlined, TeamOutlined, ThunderboltOutlined, UserOutlined,
} from '@ant-design/icons'

const { Header, Sider, Content } = Layout
const { Title, Text } = Typography

function useReload() { const [tick, setTick] = useState(0); return [tick, () => setTick((v) => v + 1)] as const }
function flatten(nodes: Department[]): Department[] { return nodes.flatMap((n) => [n, ...flatten(n.children || [])]) }
function statusLabel(value: string, t: (key: string, fallback?: string) => string) { const key = ({ false_positive: 'falsePositive', not_configured: 'notConfigured' } as Record<string, string>)[value] || value; return t(key, value.replaceAll('_', ' ')) }
function StatusTag({ value }: { value: string }) { const { t } = useI18n(); const color = ['active', 'running', 'published', 'approved', 'healthy', 'indexed', 'configured'].includes(value) ? 'green' : ['disabled', 'stopped', 'rejected', 'failed', 'down', 'critical'].includes(value) ? 'red' : 'gold'; return <Tag color={color}>{statusLabel(value, t)}</Tag> }
function ErrorBox({ error }: { error: unknown }) { const { t } = useI18n(); if (!error) return null; const e = error as ApiError; return <Alert type="error" showIcon message={e.code ? t(`error.${e.code}`, e.message) : e.message || t('errorFallback')} style={{ marginBottom: 16 }} /> }
function PageHeader({ title, subtitle, action }: { title: string; subtitle: string; action?: ReactNode }) { return <div className="page-heading"><div><h1 className="page-title">{title}</h1><div className="page-subtitle">{subtitle}</div></div>{action}</div> }
function fmtDate(value?: string) { const { formatDate } = useI18n(); return formatDate(value) }
function saveMessage(text: string) { message.success(text) }

function App() {
  const [user, setUser] = useState<User | null>(null); const [loading, setLoading] = useState(true)
  useEffect(() => { api.get<User>('/auth/me').then(setUser).catch(() => setUser(null)).finally(() => setLoading(false)) }, [])
  if (loading) return <div className="center-screen"><Spin size="large" /></div>
  return user ? <AppShell user={user} onLogout={() => setUser(null)} /> : <Login onLoggedIn={setUser} />
}

function Login({ onLoggedIn }: { onLoggedIn: (user: User) => void }) {
  const { t } = useI18n(); const [busy, setBusy] = useState(false); const [error, setError] = useState<unknown>()
  return <div className="login-screen"><div className="login-glow" /><Card className="login-card" bordered={false}><div className="login-brand"><span className="app-logo-mark">H</span><span className="brand">{t('appName')}</span></div><Text type="secondary">{t('subtitle')}</Text><Title level={2} style={{ marginTop: 30, marginBottom: 4 }}>{t('signIn')}</Title><Text type="secondary">{t('organization')}</Text><ErrorBox error={error} /><Form layout="vertical" style={{ marginTop: 24 }} onFinish={async (v) => { setBusy(true); setError(undefined); try { onLoggedIn(await api.login(v.username, v.password)) } catch (e) { setError(e) } finally { setBusy(false) } }}><Form.Item label={t('username')} name="username" rules={[{ required: true }]}><Input size="large" prefix={<UserOutlined />} placeholder="admin" /></Form.Item><Form.Item label={t('password')} name="password" rules={[{ required: true }]}><Input.Password size="large" /></Form.Item><Button type="primary" htmlType="submit" size="large" block loading={busy}>{t('signIn')}</Button></Form><div className="demo-hint">Demo: <b>admin</b> / <b>ChangeMe-Admin-2026!</b></div></Card></div>
}

function AppShell({ user, onLogout }: { user: User; onLogout: () => void }) {
  const { t, locale, setLocale } = useI18n(); const location = useLocation(); const navigate = useNavigate(); const [collapsed, setCollapsed] = useState(false); const [notifications, setNotifications] = useState<any[]>([])
  useEffect(() => { api.get<any[]>('/notifications').then(setNotifications).catch(() => undefined) }, [location.pathname])
  const item = (key: string, icon: ReactNode, label: string) => ({ key, icon, label: <Link to={key}>{label}</Link> })
  const menuItems: MenuProps['items'] = [item('/', <DashboardOutlined />, t('overview')), { type: 'group', label: t('organization'), children: [item('/users', <TeamOutlined />, t('users')), item('/departments', <ApartmentOutlined />, t('departments')), item('/roles', <SafetyCertificateOutlined />, t('roles')), item('/profile-templates', <AppstoreOutlined />, t('profileTemplates'))] }, { type: 'group', label: t('agents'), children: [item('/profiles', <AppstoreOutlined />, t('profiles')), item('/runtimes', <MonitorOutlined />, t('runtimes')), item('/runtime-templates', <MonitorOutlined />, t('runtimeTemplates'))] }, { type: 'group', label: t('resources'), children: [item('/models', <ThunderboltOutlined />, t('models')), item('/model-providers', <ThunderboltOutlined />, t('providers')), item('/skills', <CodeOutlined />, t('skills')), item('/knowledge-bases', <BookOutlined />, t('knowledge')), item('/secrets', <KeyOutlined />, t('secrets'))] }, { type: 'group', label: t('governance'), children: [item('/approvals', <CheckCircleOutlined />, t('approvals')), item('/skill-reviews', <FileSearchOutlined />, t('skillReviews')), item('/risk-events', <SafetyCertificateOutlined />, t('risks')), item('/audit-logs', <AuditOutlined />, t('audit')), item('/usage', <BarChartOutlined />, t('usage')), item('/quotas', <BarChartOutlined />, t('quotas'))] }, { type: 'group', label: t('system'), children: [item('/health', <MonitorOutlined />, t('health')), item('/notifications', <Badge count={notifications.filter((n) => n.status === 'unread').length} size="small"><BellIcon /></Badge>, t('notifications')), item('/settings', <SettingOutlined />, t('settings'))] }]
  const selected = location.pathname === '/' ? '/' : `/${location.pathname.split('/')[1]}`
  const crumbs = location.pathname === '/' ? [t('overview')] : location.pathname.slice(1).split('/').map((v) => v.replaceAll('-', ' ')).map((v) => v.replace(/^./, (c) => c.toUpperCase()))
  const userMenu: MenuProps['items'] = [{ key: 'profile', label: t('details') }, { key: 'logout', icon: <LogoutOutlined />, label: t('signOut') }]
  return <Layout style={{ minHeight: '100vh' }}><Sider collapsible collapsed={collapsed} trigger={null} width={248}><div className="app-logo"><span className="app-logo-mark">H</span>{!collapsed && <span className="brand">{t('appName')}</span>}</div><Menu theme="dark" mode="inline" selectedKeys={[selected]} items={menuItems} /></Sider><Layout><Header style={{ background: '#fff', padding: '0 26px', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}><Button type="text" icon={collapsed ? <MenuUnfoldOutlined /> : <MenuFoldOutlined />} onClick={() => setCollapsed(!collapsed)} /><Space><Select size="small" value={locale} onChange={setLocale} options={[{ value: 'en-US', label: t('english') }, { value: 'zh-CN', label: t('chinese') }]} /><Dropdown menu={{ items: userMenu, onClick: async ({ key }) => { if (key === 'profile') navigate('/profile'); if (key === 'logout') { await api.post('/auth/logout', {}); onLogout() } } }}><Button type="text"><Avatar size="small" style={{ background: '#315efb', marginRight: 8 }}>{user.display_name.slice(0, 1)}</Avatar>{user.display_name}<DownOutlined style={{ fontSize: 11, marginLeft: 8 }} /></Button></Dropdown></Space></Header><Content style={{ padding: '24px 28px' }}><Breadcrumb items={crumbs.map((label, i) => ({ title: i === 0 && crumbs.length > 1 ? <Link to="/">{t('overview')}</Link> : label }))} style={{ marginBottom: 22 }} /><Routes><Route path="/" element={<Dashboard />} /><Route path="/users" element={<Users />} /><Route path="/departments" element={<Departments />} /><Route path="/roles" element={<Roles />} /><Route path="/profile-templates" element={<ProfileTemplates />} /><Route path="/profiles" element={<Profiles />} /><Route path="/runtimes" element={<Runtimes />} /><Route path="/runtime-templates" element={<RuntimeTemplates />} /><Route path="/models" element={<Models />} /><Route path="/model-providers" element={<ModelProviders />} /><Route path="/skills" element={<Skills reviewOnly={false} />} /><Route path="/skill-reviews" element={<Skills reviewOnly />} /><Route path="/knowledge-bases" element={<KnowledgeBases />} /><Route path="/secrets" element={<Secrets />} /><Route path="/approvals" element={<Approvals />} /><Route path="/risk-events" element={<RiskEvents />} /><Route path="/audit-logs" element={<AuditLogs />} /><Route path="/usage" element={<Usage />} /><Route path="/quotas" element={<Quotas />} /><Route path="/health" element={<Health />} /><Route path="/notifications" element={<Notifications />} /><Route path="/settings" element={<Settings />} /><Route path="/profile" element={<CurrentProfile user={user} />} /></Routes></Content></Layout></Layout>
}
function BellIcon() { return <span style={{ display: 'inline-block', width: 18 }}>●</span> }

function Dashboard() {
  const { t } = useI18n(); const [data, setData] = useState<any>(); const [extra, setExtra] = useState<any>(); const [error, setError] = useState<unknown>(); const [tick, reload] = useReload()
  useEffect(() => { Promise.all([api.get<any>('/dashboard'), api.get<any>('/dashboard/phase2')]).then(([a, b]) => { setData(a); setExtra(b) }).catch(setError) }, [tick])
  const c = data?.counts || {}; const cards = [[t('totalUsers'), c.users, <TeamOutlined />], [t('activeUsers'), c.active_users, <UserOutlined />], [t('highRisk'), (extra?.high_risk || 0) + (extra?.critical_risk || 0), <SafetyCertificateOutlined />], [t('pendingApprovals'), extra?.pending_approvals, <CheckCircleOutlined />], [t('runtimeErrors'), extra?.runtime_errors, <MonitorOutlined />], [t('tokenToday'), extra?.token_today || data?.usage?.today_tokens, <BarChartOutlined />]]
  return <><PageHeader title={t('overview')} subtitle={t('subtitle')} action={<Button onClick={reload}>{t('update')}</Button>} /><ErrorBox error={error} /><Row gutter={[16, 16]}>{cards.map(([label, value, icon]) => <Col xs={12} lg={4} key={label as string}><Card className="stat-card"><Statistic title={label as string} value={value as number || 0} prefix={icon as ReactNode} /></Card></Col>)}</Row><Row gutter={[16, 16]} style={{ marginTop: 16 }}><Col xs={24} lg={16}><Card className="content-card" title={t('attention')}><Space direction="vertical" style={{ width: '100%' }}>{[['critical_risk', t('critical'), '/risk-events'], ['high_risk', t('highRisk'), '/risk-events'], ['pending_approvals', t('pendingApprovals'), '/approvals'], ['runtime_errors', t('runtimeErrors'), '/runtimes']].filter(([key]) => Number(extra?.[key] || 0) > 0).map(([key, label, path]) => <Link key={key as string} to={path as string}><Alert type={key === 'critical_risk' ? 'error' : 'warning'} showIcon message={`${label}: ${extra?.[key]}`} /></Link>)}{!extra || Object.values(extra).every((v) => !Number(v)) ? <Empty image={Empty.PRESENTED_IMAGE_SIMPLE} description={t('empty')} /> : null}</Space></Card></Col><Col xs={24} lg={8}><Card className="content-card" title={t('recentActivity')}><Text type="secondary">{t('models')} · {c.profiles || 0} {t('profiles')}</Text><Divider /><Text type="secondary">{t('runtimes')} · {data?.runtime_status?.running || 0} {statusLabel('running', t)}</Text></Card></Col></Row></>
}

function Users() {
  const { t } = useI18n(); const [users, setUsers] = useState<User[]>([]); const [departments, setDepartments] = useState<Department[]>([]); const [roles, setRoles] = useState<any[]>([]); const [selected, setSelected] = useState<User>(); const [userRoles, setUserRoles] = useState<any[]>([]); const [effective, setEffective] = useState<any[]>([]); const [open, setOpen] = useState(false); const [roleOpen, setRoleOpen] = useState(false); const [editing, setEditing] = useState<User>(); const [form] = Form.useForm(); const [roleForm] = Form.useForm(); const [tick, reload] = useReload(); const [error, setError] = useState<unknown>()
  const load = () => Promise.all([api.get<User[]>('/users'), api.get<Department[]>('/departments/tree'), api.get<any[]>('/roles/manage')]).then(([u, d, r]) => { setUsers(u); setDepartments(d); setRoles(r) }).catch(setError)
  useEffect(() => { load() }, [tick])
  const showDetail = async (u: User) => { setSelected(u); Promise.all([api.get<any[]>(`/users/${u.id}/roles`), api.get<any[]>(`/users/${u.id}/effective-permissions`)]).then(([r, p]) => { setUserRoles(r); setEffective(p) }).catch(setError) }
  const close = () => { setOpen(false); setEditing(undefined); form.resetFields() }
  return <><PageHeader title={t('users')} subtitle={t('organization')} action={<Button type="primary" icon={<UserOutlined />} onClick={() => setOpen(true)}>{t('create')}</Button>} /><ErrorBox error={error} /><Card className="content-card"><Table rowKey="id" dataSource={users} scroll={{ x: 1100 }} columns={[{ title: t('name'), render: (_: unknown, r: User) => <Button type="link" onClick={() => showDetail(r)}>{r.display_name}<div className="muted">@{r.username}</div></Button> }, { title: t('email'), dataIndex: 'email' }, { title: t('departments'), dataIndex: 'department' }, { title: t('roles'), render: (_: unknown, r: User) => <Space wrap>{r.roles.map((x) => <Tag key={x}>{x}</Tag>)}</Space> }, { title: t('status'), render: (_: unknown, r: User) => <StatusTag value={r.status} /> }, { title: t('actions'), render: (_: unknown, r: User) => <Space><Button size="small" onClick={() => { setEditing(r); form.setFieldsValue({ display_name: r.display_name, email: r.email, department_id: flatten(departments).find((d) => d.name === r.department)?.id }); setOpen(true) }}>{t('edit')}</Button><Button size="small" danger={r.status === 'active'} onClick={async () => { try { await api.post(`/users/${r.id}/status`, { status: r.status === 'active' ? 'suspended' : 'active' }); reload() } catch (e) { setError(e) } }}>{r.status === 'active' ? t('suspend') : t('activate')}</Button></Space> }]} /></Card><Modal title={editing ? t('edit') : t('create')} open={open} onCancel={close} footer={null}><Form form={form} layout="vertical" onFinish={async (v) => { try { editing ? await api.put(`/users/${editing.id}`, v) : await api.post('/users', v); saveMessage(t('saved')); close(); reload() } catch (e) { setError(e) } }}><Form.Item label={t('username')} name="username" rules={[{ required: !editing }]}><Input disabled={!!editing} /></Form.Item><Form.Item label={t('name')} name="display_name" rules={[{ required: true }]}><Input /></Form.Item><Form.Item label={t('email')} name="email" rules={[{ required: true, type: 'email' }]}><Input /></Form.Item>{!editing && <Form.Item label={t('password')} name="password" rules={[{ required: true, min: 12 }]}><Input.Password /></Form.Item>}<Form.Item label={t('departments')} name="department_id"><Select allowClear options={flatten(departments).map((d) => ({ value: d.id, label: d.name }))} /></Form.Item><Button type="primary" htmlType="submit" block>{t('save')}</Button></Form></Modal><Drawer title={`${t('details')} · ${selected?.display_name || ''}`} open={!!selected} onClose={() => setSelected(undefined)} width={720}><Tabs items={[{ key: 'roles', label: t('roles'), children: <><Space style={{ marginBottom: 16 }}><Button type="primary" onClick={() => setRoleOpen(true)}>{t('assignRole')}</Button></Space><Table size="small" rowKey={(r) => `${r.id}-${r.scope}`} dataSource={userRoles} columns={[{ title: t('roles'), dataIndex: 'name' }, { title: t('scope'), dataIndex: 'scope' }, { title: t('departments'), dataIndex: 'department' }, { title: t('actions'), render: (_: unknown, r: any) => <Popconfirm title={t('delete')} onConfirm={async () => { await api.delete(`/users/${selected?.id}/roles/${r.id}`); showDetail(selected!); reload() }}><Button size="small" danger>{t('delete')}</Button></Popconfirm> }]} /></> }, { key: 'permissions', label: t('effectivePermissions'), children: <Table size="small" rowKey={(r) => `${r.permission}-${r.source_role}-${r.scope}`} dataSource={effective} columns={[{ title: t('permission'), dataIndex: 'permission' }, { title: t('sourceRole'), dataIndex: 'source_role' }, { title: t('scope'), dataIndex: 'scope' }, { title: t('sourceBinding'), dataIndex: 'source_binding' }]} /> }]} /></Drawer><Modal title={t('assignRole')} open={roleOpen} onCancel={() => setRoleOpen(false)} footer={null}><Form form={roleForm} layout="vertical" onFinish={async (v) => { try { await api.post(`/users/${selected?.id}/roles`, v); saveMessage(t('saved')); setRoleOpen(false); roleForm.resetFields(); showDetail(selected!); reload() } catch (e) { setError(e) } }}><Form.Item label={t('roles')} name="role_id" rules={[{ required: true }]}><Select options={roles.map((r) => ({ value: r.id, label: r.name }))} /></Form.Item><Form.Item label={t('scope')} name="scope" initialValue="user"><Select options={['global', 'organization', 'department', 'user', 'profile'].map((v) => ({ value: v, label: v }))} /></Form.Item><Form.Item label={t('departments')} name="department_id"><Select allowClear options={flatten(departments).map((d) => ({ value: d.id, label: d.name }))} /></Form.Item><Button type="primary" htmlType="submit" block>{t('save')}</Button></Form></Modal></>
}

function Departments() { const { t } = useI18n(); const [data, setData] = useState<Department[]>([]); const [open, setOpen] = useState(false); const [editing, setEditing] = useState<Department>(); const [form] = Form.useForm(); const [tick, reload] = useReload(); const [error, setError] = useState<unknown>(); useEffect(() => { api.get<Department[]>('/departments/tree').then(setData).catch(setError) }, [tick]); const all = flatten(data); const render = (nodes: Department[]): any[] => nodes.map((d) => ({ key: d.id, title: <Space><span>{d.name}</span><Tag>{d.member_count}</Tag><Button type="link" size="small" onClick={(e) => { e.stopPropagation(); setEditing(d); form.setFieldsValue(d); setOpen(true) }}>{t('edit')}</Button></Space>, children: render(d.children || []) })); return <><PageHeader title={t('departments')} subtitle={t('organization')} action={<Button type="primary" onClick={() => { setEditing(undefined); form.resetFields(); setOpen(true) }}>{t('create')}</Button>} /><ErrorBox error={error} /><Row gutter={16}><Col xs={24} lg={15}><Card className="content-card"><Tree showLine defaultExpandAll treeData={render(data)} /></Card></Col><Col xs={24} lg={9}><Card className="content-card"><Table size="small" rowKey="id" pagination={false} dataSource={all} columns={[{ title: t('name'), dataIndex: 'name' }, { title: t('users'), dataIndex: 'member_count' }]} /></Card></Col></Row><Modal title={editing ? t('edit') : t('create')} open={open} onCancel={() => setOpen(false)} footer={null}><Form form={form} layout="vertical" onFinish={async (v) => { try { editing ? await api.put(`/departments/${editing.id}`, v) : await api.post('/departments', v); saveMessage(t('saved')); setOpen(false); reload() } catch (e) { setError(e) } }}><Form.Item name="name" label={t('name')} rules={[{ required: true }]}><Input /></Form.Item><Form.Item name="description" label={t('description')}><Input.TextArea /></Form.Item><Form.Item name="parent_id" label={t('departments')}><Select allowClear options={all.filter((d) => d.id !== editing?.id).map((d) => ({ value: d.id, label: d.name }))} /></Form.Item><Button type="primary" htmlType="submit" block>{t('save')}</Button></Form></Modal></> }

const permissionCatalog = ['user.read', 'user.create', 'user.update', 'department.manage', 'profile.create', 'runtime.manage', 'runtime_template.manage', 'profile_template.manage', 'role.read', 'role.assign', 'role.manage', 'security.policy.manage', 'model_provider.manage', 'secret.manage', 'skill.read', 'skill.submit', 'skill.review', 'skill.publish', 'skill.artifact.manage', 'knowledge.read', 'knowledge.manage', 'knowledge.document.manage', 'approval.create', 'approval.review', 'risk.read', 'risk.manage', 'audit.read', 'audit.export', 'settings.manage', 'quota.manage']
function Roles() { const { t } = useI18n(); const [data, setData] = useState<any[]>([]); const [detail, setDetail] = useState<any>(); const [open, setOpen] = useState(false); const [form] = Form.useForm(); const [error, setError] = useState<unknown>(); const [tick, reload] = useReload(); useEffect(() => { api.get<any[]>('/roles/manage').then(setData).catch(setError) }, [tick]); const openDetail = async (id: number) => { try { setDetail(await api.get<any>(`/roles/${id}`)) } catch (e) { setError(e) } }; return <><PageHeader title={t('roles')} subtitle={t('scopes')} action={<Button type="primary" onClick={() => { form.resetFields(); setOpen(true) }}>{t('create')}</Button>} /><ErrorBox error={error} /><Card className="content-card"><Table rowKey="id" dataSource={data} columns={[{ title: t('name'), render: (_: unknown, r: any) => <Button type="link" onClick={() => openDetail(r.id)}>{r.name}{r.is_system && <Tag color="blue" style={{ marginLeft: 8 }}>System</Tag>}</Button> }, { title: t('members'), dataIndex: 'members' }, { title: t('permissions'), dataIndex: 'permission_count' }, { title: t('createdAt'), dataIndex: 'created_at', render: fmtDate }]} /></Card><Modal title={t('create')} open={open} onCancel={() => setOpen(false)} footer={null}><Form form={form} layout="vertical" onFinish={async (v) => { try { await api.post('/roles/manage', v); saveMessage(t('created')); setOpen(false); reload() } catch (e) { setError(e) } }}><Form.Item name="name" label={t('name')} rules={[{ required: true }]}><Input /></Form.Item><Form.Item name="description" label={t('description')}><Input.TextArea /></Form.Item><Form.Item name="permissions" label={t('permissions')}><Checkbox.Group options={permissionCatalog.map((value) => ({ label: value, value }))} /></Form.Item><Button type="primary" htmlType="submit" block>{t('save')}</Button></Form></Modal><Drawer title={`${t('details')} · ${detail?.name || ''}`} open={!!detail} onClose={() => setDetail(undefined)} width={640}>{detail && <Tabs items={[{ key: 'general', label: t('general'), children: <Descriptions column={1} items={[{ key: '1', label: t('name'), children: detail.name }, { key: '2', label: t('description'), children: detail.description }, { key: '3', label: t('status'), children: detail.is_system ? t('systemStatus') : t('custom') }]} /> }, { key: 'members', label: t('members'), children: <Table size="small" rowKey="id" dataSource={detail.members || []} columns={[{ title: t('name'), dataIndex: 'display_name' }, { title: t('username'), dataIndex: 'username' }, { title: t('scope'), dataIndex: 'scope' }]} /> }, { key: 'scopes', label: t('scopes'), children: <Space wrap>{(detail.scopes || []).map((scope: string) => <Tag key={scope}>{scope}</Tag>)}</Space> }, { key: 'permissions', label: t('permissions'), children: <><Checkbox.Group style={{ display: 'grid', gap: 8 }} value={detail.permissions} options={permissionCatalog.map((value) => ({ label: value, value }))} onChange={async (values) => { try { await api.put(`/roles/${detail.id}/permissions`, { permissions: values }); setDetail({ ...detail, permissions: values }); reload() } catch (e) { setError(e) } }} /></> }, { key: 'history', label: t('changeHistory'), children: <ChangeHistory resource="role" id={detail.id} /> }]} />}</Drawer></> }
function ChangeHistory({ resource, id }: { resource: string; id: number }) { const { t } = useI18n(); const [data, setData] = useState<any[]>([]); useEffect(() => { api.get<any[]>(`/roles/${id}/history`).then(setData).catch(() => undefined) }, [resource, id]); return <Table size="small" rowKey="id" dataSource={data} columns={[{ title: t('createdAt'), dataIndex: 'created_at', render: fmtDate }, { title: t('owner'), dataIndex: 'actor_user_id' }, { title: t('before'), dataIndex: 'before', render: (v) => <pre>{JSON.stringify(v)}</pre> }, { title: t('after'), dataIndex: 'after', render: (v) => <pre>{JSON.stringify(v)}</pre> }]} /> }

